/* =============================================================================
   SRCH-01 · Chips de filtro editables (spec §3)
   ============================================================================= */

.chipsRow {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 12px;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 10px;
  background: var(--bw-deep-steel);
  border-radius: 20px;
  font-size: 12px;
  font-weight: 500;
  color: var(--bw-on-dark-hover);
  cursor: default;
}

.chipLabel {
  color: var(--bw-on-dark-soft);
  font-size: 11px;
  margin-right: 2px;
}

.chipValue {
  /* Hereda el color del chip. */
}

.chipX {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--bw-on-dark-dim);
  font-size: 14px;
  line-height: 1;
  padding: 0 0 0 3px;
  display: flex;
  align-items: center;
  transition: color 0.12s;
}

.chipX:hover {
  color: var(--bw-danger-light);
}

.chipAdd {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 10px;
  background: transparent;
  border: 1.5px dashed var(--bw-input-placeholder);
  border-radius: 20px;
  font-size: 12px;
  font-weight: 500;
  color: var(--bw-steel-mist);
  cursor: pointer;
  transition: all 0.12s;
  font-family: inherit;
}

.chipAdd:hover {
  border-color: var(--bw-calibration-blue);
  color: var(--bw-calibration-blue);
}

.chipAdd i {
  font-size: 13px;
}

.form {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.input {
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius-hamburger);
  padding: 6px 9px;
  font-size: 12px;
  color: var(--bw-deep-steel);
  outline: none;
  /* El HTML aprobado usa inputs blancos; la paleta no define blanco, y
     --bw-surface-mist es el neutro más claro disponible. */
  background: var(--bw-surface-mist);
  font-family: inherit;
  transition: border-color 0.15s;
}

.input:focus {
  border-color: var(--bw-calibration-blue);
}

.fieldSelect {
  min-width: 130px;
}

.valueSelect {
  min-width: 160px;
}

.valueInput {
  min-width: 140px;
}

.addBtn {
  height: 30px;
  padding: 0 14px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: var(--bw-radius-hamburger);
  color: var(--bw-on-dark-hover);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  font-family: inherit;
  white-space: nowrap;
}

.addBtn:hover {
  opacity: 0.87;
}

