import { useState, type ChangeEvent, type FormEvent } from 'react';
import {
  activeChips,
  withoutChip,
  ZONES,
  ZONE_LABELS,
  type ChipKey,
  type SearchCriteria,
} from '../../lib/search';
import styles from './FilterChips.module.css';

interface FilterChipsProps {
  criteria: SearchCriteria;
  onChange: (next: SearchCriteria) => void;
}

/**
 * Las cinco opciones de «Campo» (spec §3, tabla de chips). El `value` es una
 * clave estable del criterio; la etiqueta visible es el literal de la spec.
 */
const FIELD_OPTIONS: { value: ChipKey; label: string }[] = [
  { value: 'partNumber', label: 'Ref' },
  { value: 'brand', label: 'Marca' },
  { value: 'minQuantity', label: 'Qty mín' },
  { value: 'zone', label: 'Zona' },
  { value: 'maxLeadTimeDays', label: 'Lead time máx' },
];

function placeholderFor(field: ChipKey): string {
  switch (field) {
    case 'partNumber':
      return '6205-2RS';
    case 'brand':
      return 'SKF, FAG, NSK…';
    case 'minQuantity':
      return '500';
    case 'maxLeadTimeDays':
      return '7';
    case 'zone':
      return '';
  }
}

/**
 * Chips de filtro editables (spec §3).
 *
 * Presentacional y totalmente controlado: no guarda criterios, los recibe y
 * emite los nuevos enteros. Su único estado propio es el formulario inline
 * de «+ Filtro»: si está abierto y lo que hay tecleado.
 */
export function FilterChips({ criteria, onChange }: FilterChipsProps) {
  const [open, setOpen] = useState(false);
  const [field, setField] = useState<ChipKey>('partNumber');
  const [value, setValue] = useState('');

  function handleFieldChange(e: ChangeEvent<HTMLSelectElement>) {
    setField(e.target.value as ChipKey);
    // Un texto de Ref no es un código de zona; al cambiar de campo se limpia.
    setValue('');
  }

  function handleSubmit(e: FormEvent) {
    e.preventDefault();
    const v = value.trim();
    if (!v) return;
    switch (field) {
      case 'partNumber':
        onChange({ ...criteria, partNumber: v });
        break;
      case 'brand':
        onChange({ ...criteria, brand: v });
        break;
      case 'minQuantity':
        onChange({ ...criteria, minQuantity: Number(v) });
        break;
      case 'zone': {
        const zone = ZONES.find((z) => z === v);
        if (zone) onChange({ ...criteria, zone });
        break;
      }
      case 'maxLeadTimeDays':
        onChange({ ...criteria, maxLeadTimeDays: Number(v) });
        break;
    }
    setValue('');
    setField('partNumber');
    setOpen(false);
  }

  return (
    <div className={styles.chipsRow}>
      {activeChips(criteria).map((chip) => (
        <span key={chip.key} className={styles.chip}>
          <span className={styles.chipLabel}>{chip.label}</span>
          <span className={styles.chipValue}>{chip.value}</span>
          <button
            type="button"
            className={styles.chipX}
            aria-label={`Quitar filtro ${chip.label}`}
            onClick={() => onChange(withoutChip(criteria, chip.key))}
          >
            ×
          </button>
        </span>
      ))}

      <button
        type="button"
        className={styles.chipAdd}
        aria-expanded={open}
        onClick={() => setOpen((o) => !o)}
      >
        <i className="ti ti-plus" aria-hidden="true" />
        Filtro
      </button>

      {open && (
        <form className={styles.form} onSubmit={handleSubmit}>
          <select
            className={`${styles.input} ${styles.fieldSelect}`}
            aria-label="Campo"
            value={field}
            onChange={handleFieldChange}
          >
            {FIELD_OPTIONS.map((o) => (
              <option key={o.value} value={o.value}>
                {o.label}
              </option>
            ))}
          </select>

          {field === 'zone' ? (
            <select
              className={`${styles.input} ${styles.valueSelect}`}
              aria-label="Valor"
              value={value}
              onChange={(e) => setValue(e.target.value)}
            >
              <option value="">Elige una zona…</option>
              {ZONES.map((z) => (
                <option key={z} value={z}>
                  {ZONE_LABELS[z]}
                </option>
              ))}
            </select>
          ) : (
            <input
              className={`${styles.input} ${styles.valueInput}`}
              aria-label="Valor"
              type={field === 'minQuantity' || field === 'maxLeadTimeDays' ? 'number' : 'text'}
              min={field === 'minQuantity' || field === 'maxLeadTimeDays' ? 0 : undefined}
              step={field === 'minQuantity' || field === 'maxLeadTimeDays' ? 1 : undefined}
              value={value}
              onChange={(e) => setValue(e.target.value)}
              placeholder={placeholderFor(field)}
            />
          )}

          <button type="submit" className={styles.addBtn}>
            Añadir
          </button>
        </form>
      )}
    </div>
  );
}

