/* =============================================================================
   SRCH-01 · Tabla de resultados (spec §3)
   Diez columnas en orden fijo e inamovible (§7). Se ordenan filas, nunca
   columnas; la ordenación por cabecera la hace la pantalla vía sortRows.
   ============================================================================= */

.table {
  width: 100%;
  border-collapse: collapse;
  min-width: 860px;
  /* La tabla aprobada es blanca; el neutro más claro de la paleta es
     --bw-surface-mist (#F8F9FB). No hay token blanco. */
  background: var(--bw-surface-mist);
}

.table th {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--bw-input-placeholder);
  padding: 10px;
  text-align: left;
  border-bottom: 1px solid var(--bw-cold-white);
  white-space: nowrap;
  position: sticky;
  top: 0;
  background: var(--bw-surface-mist);
  z-index: 1;
}

.table .thChk {
  width: 36px;
  padding: 10px 8px 10px 14px;
}

.table td {
  padding: 10px;
  border-bottom: 1px solid var(--bw-divider-mist);
  vertical-align: middle;
}

.table .tdChk {
  padding: 10px 8px 10px 14px;
}

.table tr:last-child td {
  border-bottom: none;
}

.checkbox {
  width: 15px;
  height: 15px;
  accent-color: var(--bw-calibration-blue);
  cursor: pointer;
}

.cellRef {
  font-family: var(--bw-font-mono);
  font-size: 12px;
  color: var(--bw-deep-steel);
  white-space: nowrap;
}

.brandBadge {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  padding: 2px 7px;
  border-radius: var(--bw-radius);
  font-weight: 500;
  letter-spacing: 0.03em;
  white-space: nowrap;
  /* El HTML aprobado usa #2D3748 sobre #E2E8F0; la paleta no los tiene.
     --bw-deep-steel / --bw-on-dark-hover son los más cercanos. */
  background: var(--bw-deep-steel);
  color: var(--bw-on-dark-hover);
}

.cellQty {
  font-size: 13px;
  font-weight: 600;
  white-space: nowrap;
}

.qtyOk {
  color: var(--bw-signal-green);
}

.qtyLow {
  color: var(--bw-steel-mist);
}

.cellLead {
  font-size: 12px;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.cellOrg {
  font-size: 13px;
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.countryBadge {
  font-size: 11px;
  padding: 2px 7px;
  border-radius: var(--bw-radius);
  background: var(--bw-cold-white);
  color: var(--bw-ink-steel);
  font-weight: 500;
  white-space: nowrap;
  border: 1px solid var(--bw-line-steel);
}

.cellAge {
  font-size: 11px;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.stale {
  color: var(--bw-warning);
  font-weight: 500;
}

.favBtn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--bw-brass);
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  font-family: inherit;
  transition: opacity 0.12s;
}

.favBtn:hover {
  opacity: 0.7;
}

.favBtn[aria-pressed='true'] .favStar {
  /* Favorito marcado: la estrella pasa a ámbar, como el HTML aprobado. */
  color: var(--bw-warning);
}

.favStar {
  font-size: 14px;
}

.actionsCell {
  display: flex;
  gap: 5px;
  align-items: center;
}

.consultBtn {
  height: 28px;
  padding: 0 11px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: var(--bw-radius-hamburger);
  color: var(--bw-on-dark-hover);
  font-size: 11px;
  font-weight: 500;
  cursor: not-allowed;
  white-space: nowrap;
  font-family: inherit;
  opacity: 0.32;
}

.contactBtn {
  height: 28px;
  padding: 0 11px;
  background: transparent;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius-hamburger);
  color: var(--bw-ink-steel);
  font-size: 11px;
  font-weight: 500;
  cursor: not-allowed;
  white-space: nowrap;
  font-family: inherit;
  opacity: 0.55;
}

.consultedRow td {
  /* El HTML aprobado usa rgba(37,99,235,0.04) permanente; el token más
     cercano es --bw-row-hover-tint (0.025). */
  background: var(--bw-row-hover-tint);
}

.row:hover:not(.consultedRow) td {
  background: var(--bw-row-hover-tint);
}

.emptyCell {
  padding: 40px 16px;
  text-align: center;
  color: var(--bw-steel-mist);
  font-size: 13px;
}

.sortBtn {
  background: none;
  border: none;
  padding: 0;
  font: inherit;
  color: inherit;
  text-transform: inherit;
  letter-spacing: inherit;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

.sortable:not(.sortAsc):not(.sortDesc)::after {
  content: ' ·';
  opacity: 0.3;
}

.sortAsc {
  color: var(--bw-calibration-blue);
}

.sortAsc::after {
  content: ' ↑';
}

.sortDesc {
  color: var(--bw-calibration-blue);
}

.sortDesc::after {
  content: ' ↓';
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

