import {
  ageLabel,
  ageLevel,
  daysSince,
  countryName,
  leadTimeLabel,
  meetsMinQuantity,
  quantityLabel,
  type SearchResultRow,
  type Sort,
  type SortColumn,
} from '../../lib/search';
import styles from './ResultsTable.module.css';

interface ResultsTableProps {
  rows: SearchResultRow[];
  sort: Sort | null;
  selected: ReadonlySet<string>;
  minQuantity: number | null;
  now?: Date;
  onSort: (column: SortColumn) => void;
  onToggleRow: (lineId: string) => void;
  onToggleFavorite: (orgId: string) => void;
  onConsult: (lineId: string) => void;
  onContact: (orgId: string) => void;
}

/**
 * Tabla de resultados de SRCH-01, escrita a mano.
 *
 * Presentacional: pinta las filas que recibe EN EL ORDEN QUE LAS RECIBE
 * (ordenar es de la pantalla) y no carga datos. El estado vacío vive aquí,
 * dentro de la tabla, porque «no hay filas» es un estado de la lista.
 */
export function ResultsTable({
  rows,
  sort,
  selected,
  minQuantity,
  now,
  onSort,
  onToggleRow,
  onToggleFavorite,
  onConsult,
  onContact,
}: ResultsTableProps) {
  function sortState(column: SortColumn): 'ascending' | 'descending' | undefined {
    if (!sort || sort.column !== column) return undefined;
    return sort.direction === 'asc' ? 'ascending' : 'descending';
  }

  function sortButtonClass(column: SortColumn): string {
    const base = `${styles.sortBtn} ${styles.sortable}`;
    if (!sort || sort.column !== column) return base;
    return `${base} ${sort.direction === 'asc' ? styles.sortAsc : styles.sortDesc}`;
  }

  return (
    <table className={styles.table}>
      <thead>
        <tr>
          <th scope="col" className={styles.thChk}>
            <span className={styles.srOnly}>Selección</span>
          </th>
          <th scope="col">Referencia</th>
          <th scope="col" aria-sort={sortState('brand')}>
            <button type="button" className={sortButtonClass('brand')} onClick={() => onSort('brand')}>
              Marca
            </button>
          </th>
          <th scope="col" aria-sort={sortState('quantity')}>
            <button
              type="button"
              className={sortButtonClass('quantity')}
              onClick={() => onSort('quantity')}
            >
              Cantidad
            </button>
          </th>
          <th scope="col" aria-sort={sortState('leadTime')}>
            <button
              type="button"
              className={sortButtonClass('leadTime')}
              onClick={() => onSort('leadTime')}
            >
              Plazo
            </button>
          </th>
          <th scope="col">Empresa</th>
          <th scope="col" aria-sort={sortState('country')}>
            <button type="button" className={sortButtonClass('country')} onClick={() => onSort('country')}>
              País
            </button>
          </th>
          <th scope="col" aria-sort={sortState('age')}>
            <button type="button" className={sortButtonClass('age')} onClick={() => onSort('age')}>
              Antigüedad
            </button>
          </th>
          <th scope="col" aria-sort={sortState('favorites')}>
            <button
              type="button"
              className={sortButtonClass('favorites')}
              onClick={() => onSort('favorites')}
            >
              Favoritos
            </button>
          </th>
          <th scope="col">
            <span className={styles.srOnly}>Acciones</span>
          </th>
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => {
          const days = daysSince(row.lastUploadAt, now);
          // Spec §3: la antigüedad se marca «desactualizada» en naranja > 7 días.
          const stale = ageLevel(days) !== 'fresh';
          const byMin = meetsMinQuantity(row.quantity, minQuantity);
          return (
            <tr key={row.id} className={`${styles.row} ${row.consulted ? styles.consultedRow : ''}`}>
              <td className={styles.tdChk}>
                <input
                  type="checkbox"
                  className={styles.checkbox}
                  checked={selected.has(row.id)}
                  onChange={() => onToggleRow(row.id)}
                  aria-label={`Seleccionar ${row.partNumber}`}
                />
              </td>
              <td>
                <span className={styles.cellRef}>{row.partNumber}</span>
              </td>
              <td>
                <span className={styles.brandBadge}>{row.brand}</span>
              </td>
              <td>
                <span className={`${styles.cellQty} ${byMin ? styles.qtyOk : styles.qtyLow}`}>
                  {quantityLabel(row.quantity)}
                </span>
              </td>
              <td>
                <span className={styles.cellLead}>{leadTimeLabel(row.leadTimeDays)}</span>
              </td>
              <td>
                <span className={styles.cellOrg}>{row.orgName}</span>
              </td>
              <td>
                <span className={styles.countryBadge}>{countryName(row.country)}</span>
              </td>
              <td>
                <span className={`${styles.cellAge} ${stale ? styles.stale : ''}`}>{ageLabel(days)}</span>
              </td>
              <td>
                <button
                  type="button"
                  className={styles.favBtn}
                  aria-pressed={row.isFavorite}
                  aria-label={`${row.isFavorite ? 'Quitar favorito' : 'Añadir favorito'} a ${row.orgName}`}
                  onClick={() => onToggleFavorite(row.orgId)}
                >
                  <span className={styles.favStar} aria-hidden="true">
                    ★
                  </span>
                  <span className={styles.favCount}>{row.favoriteCount}</span>
                </button>
              </td>
              <td>
                <div className={styles.actionsCell}>
                  {/* F-100 (17-ago): ambos botones van apagados y dicen por qué.
                      Los callbacks se conservan para FL-MSG-01. */}
                  <button
                    type="button"
                    className={styles.consultBtn}
                    disabled
                    title={
                      row.consulted
                        ? 'Ya consultada anteriormente'
                        : 'La consulta de una sola línea llega en la próxima versión. Marca la fila y usa «Consultar seleccionados».'
                    }
                    onClick={() => onConsult(row.id)}
                  >
                    Consultar
                  </button>
                  <button
                    type="button"
                    className={styles.contactBtn}
                    disabled
                    title="El hilo libre con el proveedor está fuera del alcance de esta versión"
                    onClick={() => onContact(row.orgId)}
                  >
                    Contactar
                  </button>
                </div>
              </td>
            </tr>
          );
        })}
        {rows.length === 0 && (
          <tr>
            <td colSpan={10} className={styles.emptyCell}>
              No hemos encontrado stock con estos filtros.
            </td>
          </tr>
        )}
      </tbody>
    </table>
  );
}

