/* =============================================================================
   SRCH-01 · Panel de Resultados de Búsqueda
   Todos los colores salen de los tokens del design system (openspec §1).
   ============================================================================= */

.screen {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
}

.pageTitle {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin-bottom: 16px;
}

.metabar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}

.metaCount {
  font-size: 13px;
  color: var(--bw-steel-mist);
  flex: 1;
  min-width: 0;
}

.selAllBtn {
  background: none;
  border: none;
  padding: 0;
  font-family: inherit;
  font-size: 12px;
  font-weight: 500;
  color: var(--bw-calibration-blue);
  cursor: pointer;
  transition: opacity 0.12s;
  white-space: nowrap;
}

.selAllBtn:hover:not(:disabled) {
  opacity: 0.7;
}

.selAllBtn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.consultSelectedBtn {
  height: 32px;
  padding: 0 14px;
  background: var(--bw-calibration-blue);
  border: none;
  /* El HTML aprobado usa 5px; la paleta solo define 3px y 4px. */
  border-radius: var(--bw-radius-hamburger);
  color: var(--bw-on-dark-hover);
  font-family: inherit;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: opacity 0.12s;
  white-space: nowrap;
}

.consultSelectedBtn:disabled {
  opacity: 0.32;
  cursor: not-allowed;
}

.consultSelectedBtn:not(:disabled):hover {
  opacity: 0.87;
}

.watcherBtn {
  height: 32px;
  padding: 0 14px;
  background: transparent;
  /* El HTML aprobado usa rgba(184,146,74,0.4) de borde; el token más cercano
     es --bw-brass-border-strong (0.3). */
  border: 1px solid var(--bw-brass-border-strong);
  border-radius: var(--bw-radius-hamburger);
  color: var(--bw-brass);
  font-family: inherit;
  font-size: 12px;
  font-weight: 500;
  cursor: not-allowed;
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  opacity: 0.7;
}

.watcherBtn i {
  font-size: 14px;
}

.resultsZone {
  flex: 1;
  min-height: 0;
  overflow: auto;
  display: flex;
  flex-direction: column;
  /* El HTML aprobado usa blanco para la zona de tabla; la paleta no define
     blanco. --bw-surface-mist (#F8F9FB) es el neutro más claro disponible. */
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  position: relative;
}

.loadingState {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 40px;
  color: var(--bw-steel-mist);
  font-size: 13px;
}

.spinner {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 2px solid var(--bw-line-steel);
  border-top-color: var(--bw-calibration-blue);
  animation: bwSpin 0.7s linear infinite;
}

@keyframes bwSpin {
  to {
    transform: rotate(360deg);
  }
}

.errorState {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 40px;
  color: var(--bw-error-text);
  font-size: 13px;
  text-align: center;
}

.errorState p {
  margin: 0;
}

.retryBtn {
  height: 30px;
  padding: 0 14px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: var(--bw-radius-hamburger);
  color: var(--bw-on-dark-hover);
  font-family: inherit;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
}

.retryBtn:hover {
  opacity: 0.87;
}

.capNotice {
  padding: 8px 12px;
  background: var(--bw-badge-warning-bg);
  border-bottom: 1px solid var(--bw-badge-warning-border);
  color: var(--bw-warning-dark);
  font-size: 12px;
  font-weight: 500;
  flex-shrink: 0;
}

.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

