import { useEffect, useState } from 'react';
import {
  EMPTY_CRITERIA,
  fetchResults,
  meetsMinQuantity,
  metaCounterLabel,
  nextSort,
  sortRows,
  toggleFavorite,
  type SearchCriteria,
  type SearchPage,
  type Sort,
  type SortColumn,
} from '../../lib/search';
import type { MemberProfile } from '../../lib/session';
import { FilterChips } from './FilterChips';
import { ResultsTable } from './ResultsTable';
import styles from './SearchResults.module.css';

interface SearchResultsProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  /**
   * Criterios que VERA escribió en el chat (día 9, fuera de alcance).
   * Se declara porque App.tsx ya lo pasa: es la firma pública del componente.
   * No se usa en esta iteración (F-118).
   */
  veraCriteria?: SearchCriteria | null;
  /**
   * Aviso del masivo «Consultar seleccionados». El destino (crear hilos) es la
   * fila del día 10 del Plan §3; hoy el botón se habilita con ≥1 fila marcada
   * (F-100) y avisa por este callback.
   */
  onConsultSelected?: (lineIds: string[]) => void;
}

/**
 * SRCH-01 · Panel de Resultados de Búsqueda.
 *
 * Es la pantalla, no un componente de presentación: posee criterios, orden,
 * selección, carga y error, y llama a la capa de datos.
 */
export function SearchResults({ profile, now = new Date(), onConsultSelected }: SearchResultsProps) {
  const [criteria, setCriteria] = useState<SearchCriteria>(EMPTY_CRITERIA);
  const [sort, setSort] = useState<Sort | null>(null);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [page, setPage] = useState<SearchPage | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const [reloadKey, setReloadKey] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(false);
    fetchResults({ orgId: profile.orgId, memberId: profile.id, criteria })
      .then((p) => {
        if (cancelled) return;
        setPage(p);
        setLoading(false);
      })
      .catch(() => {
        if (cancelled) return;
        setPage(null);
        setError(true);
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [profile.orgId, profile.id, criteria, reloadKey]);

  function handleCriteriaChange(next: SearchCriteria) {
    setCriteria(next);
    // Los resultados cambian; una selección de filas que ya no existen no debe
    // seguir marcada.
    setSelected(new Set());
  }

  function handleSort(column: SortColumn) {
    setSort((prev) => nextSort(prev, column));
  }

  function handleToggleRow(lineId: string) {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(lineId)) next.delete(lineId);
      else next.add(lineId);
      return next;
    });
  }

  async function handleToggleFavorite(orgId: string) {
    const row = page?.rows.find((r) => r.orgId === orgId);
    if (!row || !page) return;
    try {
      await toggleFavorite(profile.id, orgId, !row.isFavorite);
      // Refetch silencioso: el recuento agregado lo mantiene el trigger de la BD.
      const next = await fetchResults({ orgId: profile.orgId, memberId: profile.id, criteria });
      setPage(next);
    } catch {
      // La spec no define mensaje para el fallo de favorito; se ignora y el
      // estado visual no cambia porque la BD es la fuente de verdad.
    }
  }

  function handleToggleSelectAll() {
    if (!page || page.rows.length === 0) return;
    const ids = page.rows.map((r) => r.id);
    const allSelected = ids.every((id) => selected.has(id));
    setSelected(allSelected ? new Set() : new Set(ids));
  }

  function handleConsultSelected() {
    const ids = Array.from(selected);
    if (ids.length === 0) return;
    onConsultSelected?.(ids);
  }

  function handleRetry() {
    setReloadKey((k) => k + 1);
  }

  const rows = page ? sortRows(page.rows, sort) : [];
  const withStock = page
    ? page.rows.filter((r) => meetsMinQuantity(r.quantity, criteria.minQuantity)).length
    : 0;
  const allSelected =
    page !== null && page.rows.length > 0 && page.rows.every((r) => selected.has(r.id));

  return (
    <div className={styles.screen}>
      <div className={styles.eyebrow}>Módulo 03 · Búsqueda Conversacional</div>
      <h1 className={styles.pageTitle}>Resultados de búsqueda</h1>

      <FilterChips criteria={criteria} onChange={handleCriteriaChange} />

      <div className={styles.metabar}>
        <div className={styles.metaCount}>
          {page ? metaCounterLabel(page.total, withStock, criteria.minQuantity) : '…'}
        </div>
        <button
          type="button"
          className={styles.selAllBtn}
          onClick={handleToggleSelectAll}
          disabled={!page || page.rows.length === 0}
        >
          {allSelected ? 'Deseleccionar todos' : 'Seleccionar todos'}
        </button>
        <button
          type="button"
          className={styles.consultSelectedBtn}
          onClick={handleConsultSelected}
          disabled={selected.size === 0}
        >
          Consultar seleccionados
        </button>
        {/* SRCH-03 (watchers) está fuera del alcance: el botón se pinta y dice
            por qué está apagado, como la subida de INV-01 (F-023 e). */}
        <button
          type="button"
          className={styles.watcherBtn}
          disabled
          title="Los watchers están fuera del alcance de esta versión"
        >
          <i className="ti ti-bell-plus" aria-hidden="true" />
          Crear watcher con estos criterios
        </button>
      </div>

      {/* Spec §6: durante la carga el spinner vive en la zona de tabla y los
          chips siguen montados y visibles. aria-busy cierra ese contrato. */}
      <div className={styles.resultsZone} aria-busy={loading}>
        {loading ? (
          <div className={styles.loadingState}>
            <span className={styles.spinner} aria-hidden="true" />
            <span className={styles.srOnly}>Cargando resultados…</span>
          </div>
        ) : error ? (
          <div className={styles.errorState} role="alert">
            <p>No se pudieron cargar los resultados. Inténtalo de nuevo.</p>
            <button type="button" className={styles.retryBtn} onClick={handleRetry}>
              Reintentar
            </button>
          </div>
        ) : (
          <>
            {page?.capped && (
              // F-023: un recorte silencioso se enseñaría como el conjunto
              // entero. El aviso es parte del contrato, VERBATIM.
              <div className={styles.capNotice} role="status">
                Mostrando los primeros 200 resultados. Afina los filtros para verlos todos.
              </div>
            )}
            <ResultsTable
              rows={rows}
              sort={sort}
              selected={selected}
              minQuantity={criteria.minQuantity}
              now={now}
              onSort={handleSort}
              onToggleRow={handleToggleRow}
              onToggleFavorite={handleToggleFavorite}
              // F-100: los botones de fila van deshabilitados y no disparan
              // nada; los callbacks se conservan para FL-MSG-01.
              onConsult={() => {}}
              onContact={() => {}}
            />
          </>
        )}
      </div>
    </div>
  );
}
